"""Bulk export: several files in one JSON response (used by the "Download selected" button)."""
import base64

from flask import Blueprint, abort, jsonify, request

from .. import db
from ..auth import login_required, require_readable_file

bp = Blueprint("export", __name__)

MAX_IDS = 50


@bp.post("/api/export")
@login_required
def export():
    body = request.get_json(silent=True) or {}
    ids = body.get("file_ids")
    if not isinstance(ids, list) or not (1 <= len(ids) <= MAX_IDS) or not all(isinstance(i, str) for i in ids):
        abort(400, description="bad_file_ids")

    placeholders = ",".join("?" for _ in ids)
    rows = db.query_all(f"SELECT id, org_id, name, mime_type, size, content FROM files WHERE id IN ({placeholders})", ids)
    by_id = {row["id"]: row for row in rows}

    # Validate every selection before serialising any file.
    for file_id in ids:
        row = by_id.get(file_id)
        if row is None:
            abort(404, description="not_found")
        require_readable_file(row)

    out = []
    for file_id in ids:
        row = by_id[file_id]
        out.append({"id": row["id"], "name": row["name"], "mime_type": row["mime_type"], "size": row["size"],
                    "content_b64": base64.b64encode(bytes(row["content"])).decode("ascii")})
    return jsonify(files=out)
